            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            Debug.Assert(value.ItemsCount >= 0 && value.ItemsCount <= 3, "value.ItemsCount out of range [0, 3]");
            {
                uint offsetValue = (uint)value.ItemsCount;
                if (!stream.SerializeBits(ref offsetValue, 2))
                {
                    return false;
                }
            }
            {
                Span<ushort> itemsSpan = value.Items.AsSpan();
                for (int i = 0; i < value.ItemsCount; i++)
                {
                    Debug.Assert(itemsSpan[i] <= 8191, "itemsSpan[i] out of range [0, 8191]");
                    {
                        uint offsetValue = (uint)itemsSpan[i];
                        if (!stream.SerializeBits(ref offsetValue, 13))
                        {
                            return false;
                        }
                    }
                }
            }
            Debug.Assert(value.SLength >= 0 && value.SLength <= 4, "value.SLength out of range [0, 4]");
            {
                uint offsetValue = (uint)value.SLength;
                if (!stream.SerializeBits(ref offsetValue, 3))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.S.AsSpan().Slice(0, value.SLength)))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.P, 32))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.Q, 29))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.R, 19))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.Tail, 4))
            {
                return false;
            }
            return true;
        }

        public static bool ReadRegainAfterAlign(ReadStream stream, ref RegainAfterAlign value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.ItemsCount, 0, 3)) // the count guards the loop (§6.3)
            {
                return false;
            }
            {
                Span<ushort> itemsSpan = value.Items.AsSpan();
                for (int i = 0; i < value.ItemsCount; i++)
                {
                    int rangeValue = 0;
                    if (!stream.SerializeInt(ref rangeValue, 0, 8191))
                    {
                        return false;
                    }
                    itemsSpan[i] = (ushort)rangeValue;
                }
            }
            if (!stream.SerializeInt(ref value.SLength, 0, 4)) // the length guards the slice (§6.3)
            {
                return false;
            }
            {
                Span<byte> bytes = value.S.AsSpan().Slice(0, value.SLength);
                if (!stream.SerializeBytes(bytes))
                {
                    return false;
                }
                if (!ValidUtf8Text(bytes)) // malformed UTF-8 or an interior null is refused (SPEC §4.7)
                {
                    return false;
                }
            }
            if (!stream.SerializeBits(ref value.P, 32))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.Q, 29))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.R, 19))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.Tail, 4))
            {
                return false;
            }
            return true;
        }
    }
}
